import { test } from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { validateMigrationCodeGenAlignment } from '../check-migration-codegen-alignment.mjs';

const HERE = dirname(fileURLToPath(import.meta.url));
const SCRIPT = join(HERE, '..', 'check-migration-codegen-alignment.mjs');
const BLANK_52 = '\n'.repeat(53);

function envWithoutBaseRef() {
    const env = { ...process.env };
    delete env.BASE_REF;
    delete env.MIGRATION_ALIGNMENT_MODE;
    return env;
}

function createStandaloneRepo() {
    const dir = mkdtempSync(join(tmpdir(), 'mig-alignment-'));
    execFileSync('git', ['init', '-q'], { cwd: dir });
    execFileSync('git', ['config', 'user.email', 'test@test.com'], { cwd: dir });
    execFileSync('git', ['config', 'user.name', 'Test'], { cwd: dir });
    execFileSync('git', ['commit', '-q', '--allow-empty', '-m', 'init'], { cwd: dir });
    return dir;
}

const VALID_CREATE_SQL = `CREATE TABLE \${flyway:defaultSchema}.[SampleWidget] (
    [ID] UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
    [Status] NVARCHAR(20) NOT NULL CHECK ([Status] IN (N'Active', N'Archived'))
);
GO${BLANK_52}-- =============================================================================
-- GENERATED BY MemberJunction CodeGen — DO NOT EDIT BY HAND
-- =============================================================================
INSERT INTO [\${mjSchema}].[Entity] ([ID], [Name], [BaseTable]) VALUES ('11111111-1111-4111-8111-111111111111', 'Sample Widgets', 'SampleWidget');
INSERT INTO [\${mjSchema}].[EntityField] ([ID], [EntityID], [Sequence], [Name]) VALUES ('22222222-2222-4222-8222-222222222222', '11111111-1111-4111-8111-111111111111', (SELECT COALESCE(MAX([Sequence]), 0) + 1 FROM [\${mjSchema}].[EntityField] WHERE [EntityID] = '11111111-1111-4111-8111-111111111111'), 'Status');
INSERT INTO [\${mjSchema}].[EntityFieldValue] ([ID], [EntityFieldID], [Sequence], [Value]) VALUES ('33333333-3333-4333-8333-333333333333', '22222222-2222-4222-8222-222222222222', 1, 'Active');
GO
CREATE VIEW [\${flyway:defaultSchema}].[vwSampleWidgets] AS SELECT w.* FROM [\${flyway:defaultSchema}].[SampleWidget] AS w;
GO
GRANT SELECT ON [\${flyway:defaultSchema}].[vwSampleWidgets] TO [cdp_UI];
GO
CREATE PROCEDURE [\${flyway:defaultSchema}].[spCreateSampleWidget] @ID uniqueidentifier, @Status nvarchar(20) AS BEGIN SELECT 1; END;
GO
CREATE PROCEDURE [\${flyway:defaultSchema}].[spUpdateSampleWidget] @ID uniqueidentifier, @Status nvarchar(20) AS BEGIN SELECT 1; END;
GO
CREATE PROCEDURE [\${flyway:defaultSchema}].[spDeleteSampleWidget] @ID uniqueidentifier AS BEGIN SELECT 1; END;
GO
CREATE TRIGGER [\${flyway:defaultSchema}].trgUpdateSampleWidget ON [\${flyway:defaultSchema}].[SampleWidget] AFTER UPDATE AS BEGIN SET NOCOUNT ON; END;
GO`;

test('--self-test passes cleanly', () => {
    const result = spawnSync(process.execPath, [SCRIPT, '--self-test'], {
        encoding: 'utf8',
        env: envWithoutBaseRef(),
    });
    assert.equal(result.status, 0, result.stdout + result.stderr);
    assert.match(result.stdout, /all \d+ self-tests passed/);
});

test('local form fails cleanly (no raw stack trace), naming the ref, when BASE_REF/origin/next does not resolve', (t) => {
    const dir = createStandaloneRepo();
    t.after(() => rmSync(dir, { recursive: true, force: true }));
    const result = spawnSync(process.execPath, [SCRIPT], {
        cwd: dir,
        encoding: 'utf8',
        env: envWithoutBaseRef(),
    });

    assert.notEqual(result.status, 0, 'unresolved base ref must not succeed');
    assert.doesNotMatch(result.stderr, /at file:\/\//, 'must not leak raw JS stack trace');
    assert.doesNotMatch(result.stderr, /node:internal/, 'must not leak raw JS stack trace');
    assert.match(result.stderr, /origin\/next/, 'must name the unresolved ref');
    assert.match(result.stderr, /BASE_REF/, 'must explain how to override ref');
    const fatalLines = (result.stdout + result.stderr).match(/fatal:/g) ?? [];
    assert.equal(fatalLines.length, 1, 'git fatal line must appear once');
});

test('CI git-diff mode validates aligned PR (T-SQL + PG + generated TS) and rejects drifted PR', (t) => {
    const dir = createStandaloneRepo();
    t.after(() => rmSync(dir, { recursive: true, force: true }));

    const baseSha = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: dir, encoding: 'utf8' }).trim();
    mkdirSync(join(dir, 'migrations'), { recursive: true });
    mkdirSync(join(dir, 'migrations-pg'), { recursive: true });
    mkdirSync(join(dir, 'packages', 'Entities', 'src', 'generated'), { recursive: true });

    const migPath = 'migrations/V202611260001__v1.0.x__Add_SampleWidget.sql';
    const pgPath = 'migrations-pg/V202611260001__v1.0.x__Add_SampleWidget.pg.sql';
    const tsPath = 'packages/Entities/src/generated/entity_subclasses.ts';

    writeFileSync(join(dir, migPath), VALID_CREATE_SQL);
    writeFileSync(join(dir, pgPath), 'CREATE TABLE "__mj"."SampleWidget" ("ID" UUID PRIMARY KEY, "Status" VARCHAR(20));\n');
    writeFileSync(join(dir, tsPath), 'export class SampleWidgetEntity { get Status(): string { return "Active"; } }\n');
    execFileSync('git', ['add', migPath, pgPath, tsPath], { cwd: dir });
    execFileSync('git', ['commit', '-q', '-m', 'aligned migration'], { cwd: dir });

    const passRun = spawnSync(process.execPath, [SCRIPT, '--base', baseSha, '--head', 'HEAD'], {
        cwd: dir,
        encoding: 'utf8',
        env: envWithoutBaseRef(),
    });
    assert.equal(passRun.status, 0, passRun.stdout + passRun.stderr);

    // Now commit a breaking migration without CodeGen or generated TS
    const badBaseSha = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: dir, encoding: 'utf8' }).trim();
    const badMig = 'migrations/V202611260002__v1.0.x__BadAlter.sql';
    writeFileSync(join(dir, badMig), 'ALTER TABLE dbo.[SampleWidget] ADD [UrgentCode] NVARCHAR(20) NOT NULL;\n');
    execFileSync('git', ['add', badMig], { cwd: dir });
    execFileSync('git', ['commit', '-q', '-m', 'unaligned breaking migration'], { cwd: dir });

    const failRun = spawnSync(process.execPath, [SCRIPT, '--base', badBaseSha, '--head', 'HEAD'], {
        cwd: dir,
        encoding: 'utf8',
        env: envWithoutBaseRef(),
    });
    assert.equal(failRun.status, 1);
    assert.match(failRun.stdout, /CODEGEN_SECTION_MISSING/);
    assert.match(failRun.stdout, /ADDITIVE_POLICY_NOT_NULL_WITHOUT_DEFAULT/);
    assert.match(failRun.stdout, /CROSS_FILE_MISSING_PG_COUNTERPART/);
    assert.match(failRun.stdout, /CROSS_FILE_MISSING_GENERATED_TS/);

    // Warn mode exits 0 with warnings
    const warnRun = spawnSync(process.execPath, [SCRIPT, '--base', badBaseSha, '--head', 'HEAD', '--mode', 'Warn'], {
        cwd: dir,
        encoding: 'utf8',
        env: envWithoutBaseRef(),
    });
    assert.equal(warnRun.status, 0);
    assert.match(warnRun.stdout, /CODEGEN_SECTION_MISSING/);
});

test('validateMigrationCodeGenAlignment enforces --allow-breaking and --min-blank-lines options', () => {
    const breaking = `-- codegen-not-required: era bump test\nDROP TABLE dbo.[OldWidget];\n`;
    const blocked = validateMigrationCodeGenAlignment({
        changedPaths: ['migrations/V202611260003__v2.0.x__Drop.sql'],
        files: [{ path: 'migrations/V202611260003__v2.0.x__Drop.sql', content: breaking }],
        repoHasPgMigrationsDir: false,
        repoHasGeneratedEntitiesDir: false,
    });
    assert.equal(blocked.passed, false);
    assert.ok(blocked.findings.some((f) => f.code === 'ADDITIVE_POLICY_DROP_TABLE'));

    const allowed = validateMigrationCodeGenAlignment({
        changedPaths: ['migrations/V202611260003__v2.0.x__Drop.sql'],
        files: [{ path: 'migrations/V202611260003__v2.0.x__Drop.sql', content: breaking }],
        config: { enforceAdditiveSchemaPolicy: false },
        repoHasPgMigrationsDir: false,
        repoHasGeneratedEntitiesDir: false,
    });
    assert.equal(allowed.passed, true);
});
